import jakarta.servlet.FilterChain
import jakarta.servlet.ServletException
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component
import org.springframework.web.filter.OncePerRequestFilter
import java.io.IOException
import java.util.concurrent.Semaphore

@Component
class ConnectionLimiterFilter(
@Value("\${app.maxConcurrentRequests:50}") private val maxConcurrentRequests: Int
) : OncePerRequestFilter() {
private val semaphore = Semaphore(maxConcurrentRequests)

@Throws(ServletException::class, IOException::class)
override fun doFilterInternal(request: HttpServletRequest, response: HttpServletResponse, filterChain: FilterChain) {
if (!semaphore.tryAcquire()) {
response.sendError(HttpServletResponse.SC_SERVICE_UNAVAILABLE, "Too many concurrent requests")
return
}
try {
filterChain.doFilter(request, response)
} finally {
semaphore.release()
}
}
},"[""import jakarta.servlet.FilterChain\r\nimport jakarta.servlet.ServletException\r\nimport jakarta.servlet.http.HttpServletRequest\r\nimport jakarta.servlet.http.HttpServletResponse\r\nimport org.springframework.beans.factory.annotation.Value\r\nimport org.springframework.stereotype.Component\r\nimport org.springframework.web.filter.OncePerRequestFilter\r\nimport java.io.IOException\r\nimport java.util.concurrent.Semaphore\r\n\r\n@Component\r\nclass ConnectionLimiterFilter(\r\n@Value(""\${app.maxConcurrentRequests:50}"") private val maxConcurrentRequests: Int\r\n) : OncePerRequestFilter() {\r\nprivate val semaphore = Semaphore(maxConcurrentRequests)\r\n\r\n@Throws(ServletException::class, IOException::class)\r\noverride fun doFilterInternal(request: HttpServletRequest, response: HttpServletResponse, filterChain: FilterChain) {\r\nif (!semaphore.tryAcquire()) {\r\nresponse.sendError(HttpServletResponse.SC_SERVICE_UNAVAILABLE, ""Too many concurrent requests"")\r\nreturn\r\n}\r\ntry {\r\nfilterChain.doFilter(request, response)\r\n} finally {\r\nsemaphore.release()\r\n}\r\n}\r\n}""]",0

import java.net.URL;
