Base = declarative_base()

class User(Base):
    __tablename__ = 'users'

    id = Column(Integer, primary_key=True)
    _global = Column("global", Boolean)

    @property
    def global(self):
        return self._global

    @global.setter
    def global(self, value):
        self._global = value
