from datetime import date
from typing import Annotated
from pydantic import BaseModel, BeforeValidator
from pydantic_core import ValidationInfo

def to_date(field_name,value,potential_formats,return_str=False):
 for fmt in potential_formats:
  try:
   parsed_date=date.strptime(value,fmt)
   return str(parsed_date) if return_str else parsed_date
  except ValueError:
   continue
 raise ValueError(f"Field '{field_name}' could not be parsed as a date")

def custom_date(potential_formats):
 def validate_date(value,info:ValidationInfo)->date:
  if isinstance(value,date):
   return value
  return to_date(info.field_name,value,potential_formats,return_str=False)
 return Annotated[date,BeforeValidator(validate_date)]

class ExampleModel(BaseModel):
 dt:custom_date(['%Y-%m-%d','%Y/%m/%d'])

# Example usage
data={'dt':'2025-03-18'}
parsed=ExampleModel(**data)
print(parsed),"[""from datetime import date\r\nfrom typing import Annotated\r\nfrom pydantic import BaseModel, BeforeValidator\r\nfrom pydantic_core import ValidationInfo\r\n\r\ndef to_date(field_name,value,potential_formats,return_str=False):\r\n for fmt in potential_formats:\r\n  try:\r\n   parsed_date=date.strptime(value,fmt)\r\n   return str(parsed_date) if return_str else parsed_date\r\n  except ValueError:\r\n   continue\r\n raise ValueError(f""Field '{field_name}' could not be parsed as a date"")\r\n\r\ndef custom_date(potential_formats):\r\n def validate_date(value,info:ValidationInfo)->date:\r\n  if isinstance(value,date):\r\n   return value\r\n  return to_date(info.field_name,value,potential_formats,return_str=False)\r\n return Annotated[date,BeforeValidator(validate_date)]\r\n\r\nclass ExampleModel(BaseModel):\r\n dt:custom_date(['%Y-%m-%d','%Y/%m/%d'])\r\n\r\n# Example usage\r\ndata={'dt':'2025-03-18'}\r\nparsed=ExampleModel(**data)\r\nprint(parsed)""]",0

import pandas as pd
import numpy as np

def safe_addition(series,value,dtype):
 info=np.iinfo(dtype)
 if ((series>info.max-value)|(series<info.min+value)).any():
  raise OverflowError("Operation would cause integer overflow!")
 return (series+value).astype(dtype)

data=[2**31-1]
s=pd.Series(data,dtype="int64") # Keep it int64 to prevent premature overflow

try:
 result=safe_addition(s,1,np.int32)
 print(result)
except OverflowError as e:
 print(e),"[""import pandas as pd\r\nimport numpy as np\r\n\r\ndef safe_addition(series,value,dtype):\r\n info=np.iinfo(dtype)\r\n if ((series>info.max-value)|(series<info.min+value)).any():\r\n  raise OverflowError(""Operation would cause integer overflow!"")\r\n return (series+value).astype(dtype)\r\n\r\ndata=[2**31-1]\r\ns=pd.Series(data,dtype=""int64"") # Keep it int64 to prevent premature overflow\r\n\r\ntry:\r\n result=safe_addition(s,1,np.int32)\r\n print(result)\r\nexcept OverflowError as e:\r\n print(e)""]",0

