from collections import deque

def max_diff_partition(nums, a, b):
    n=len(nums)
    dp=[float('-inf')]*(n+1)
    dp[0]=0
    best_split=[-1]*(n+1)

    def calc_diff(start,end):
        sub=nums[start:end]
        return max(sub)-min(sub)

    deques=[deque() for _ in range(n+1)]

    for end in range(a,n+1):
        for start in range(max(0,end-b),end-a+1):
            diff=calc_diff(start,end)
            if dp[start]+diff>dp[end]:
                dp[end]=dp[start]+diff
                best_split[end]=start

        deques[end].append(dp[end])

    if dp[n]==float('-inf'):
        return "Splitting is impossible"

    result=[]
    idx=n
    while idx>0:
        start=best_split[idx]
        result.append(nums[start:idx])
        idx=start

    return list(reversed(result))

nums=[5,8,4,5,1,3,5,1,3,1]
a,b=3,7
print(max_diff_partition(nums,a,b)),"[""from collections import deque\r\n\r\ndef max_diff_partition(nums, a, b):\r\n    n=len(nums)\r\n    dp=[float('-inf')]*(n+1)\r\n    dp[0]=0\r\n    best_split=[-1]*(n+1)\r\n\r\n    def calc_diff(start,end):\r\n        sub=nums[start:end]\r\n        return max(sub)-min(sub)\r\n\r\n    deques=[deque() for _ in range(n+1)]\r\n\r\n    for end in range(a,n+1):\r\n        for start in range(max(0,end-b),end-a+1):\r\n            diff=calc_diff(start,end)\r\n            if dp[start]+diff>dp[end]:\r\n                dp[end]=dp[start]+diff\r\n                best_split[end]=start\r\n\r\n        deques[end].append(dp[end])\r\n\r\n    if dp[n]==float('-inf'):\r\n        return ""Splitting is impossible""\r\n\r\n    result=[]\r\n    idx=n\r\n    while idx>0:\r\n        start=best_split[idx]\r\n        result.append(nums[start:idx])\r\n        idx=start\r\n\r\n    return list(reversed(result))\r\n\r\nnums=[5,8,4,5,1,3,5,1,3,1]\r\na,b=3,7\r\nprint(max_diff_partition(nums,a,b))""]",0

from fastapi import FastAPI

# --- main app ---
def lifespan(_):
 print("startup")
 yield
 print("shutdown")

app=FastAPI(lifespan=lifespan)

@app.get("/")
async def root():
 return {"message":"Hello World"}

# --- sub app ---
def sub_lifespan(_):
 print("sub startup")
 yield
 print("sub shutdown")

sub_app=FastAPI(lifespan=sub_lifespan)

@sub_app.get("/")
async def sub_root():
 return {"message":"Hello Sub World"}

app.mount("/sub",sub_app),"[""from fastapi import FastAPI\r\n\r\n# --- main app ---\r\ndef lifespan(_):\r\n print(""startup"")\r\n yield\r\n print(""shutdown"")\r\n\r\napp=FastAPI(lifespan=lifespan)\r\n\r\n@app.get(""/"")\r\nasync def root():\r\n return {""message"":""Hello World""}\r\n\r\n# --- sub app ---\r\ndef sub_lifespan(_):\r\n print(""sub startup"")\r\n yield\r\n print(""sub shutdown"")\r\n\r\nsub_app=FastAPI(lifespan=sub_lifespan)\r\n\r\n@sub_app.get(""/"")\r\nasync def sub_root():\r\n return {""message"":""Hello Sub World""}\r\n\r\napp.mount(""/sub"",sub_app)""]",0

