from dataclasses import dataclass
from typing import Protocol, runtime_checkable

@runtime_checkable
class HasA(Protocol):
    a: int

@runtime_checkable
class HasHasA(Protocol):
    hasa: HasA

@dataclass
class Inner:
    a: int

@dataclass
class Outer:
    hasa: HasA  # Explicitly use HasA instead of Inner

def func(b: HasHasA): ...

o = Outer(Inner(0))

# Ensure compatibility
assert isinstance(o.hasa, HasA)
assert isinstance(o, HasHasA)

func(o)  # Now works without errors,"[""from dataclasses import dataclass\r\nfrom typing import Protocol, runtime_checkable\r\n\r\n@runtime_checkable\r\nclass HasA(Protocol):\r\n    a: int\r\n\r\n@runtime_checkable\r\nclass HasHasA(Protocol):\r\n    hasa: HasA\r\n\r\n@dataclass\r\nclass Inner:\r\n    a: int\r\n\r\n@dataclass\r\nclass Outer:\r\n    hasa: HasA  # Explicitly use HasA instead of Inner\r\n\r\ndef func(b: HasHasA): ...\r\n\r\no = Outer(Inner(0))\r\n\r\n# Ensure compatibility\r\nassert isinstance(o.hasa, HasA)\r\nassert isinstance(o, HasHasA)\r\n\r\nfunc(o)  # Now works without errors""]",0

