import polars as pl
from tqdm import tqdm

df=pl.DataFrame({
"team":["A","A","A","B","B","C"],
"conference":["East","East","East","West","West","East"],
"points":[11,8,10,6,6,5],
"rebounds":[7,7,6,9,12,8]
})

def custom_func(x):
return x.select(pl.col("points").mean())

def pl_groupby_progress_apply(data,group_by,func):
groups=data.group_by(group_by).groups()
results=[]

for _,idx in tqdm(groups.iter_rows(),desc="Processing groups"):
group=data[idx,:]
results.append(func(group))

return pl.concat(results)

result=pl_groupby_progress_apply(df,"team",custom_func)
print(result),"[""import polars as pl\r\nfrom tqdm import tqdm\r\n\r\ndf=pl.DataFrame({\r\n""team"":[""A"",""A"",""A"",""B"",""B"",""C""],\r\n""conference"":[""East"",""East"",""East"",""West"",""West"",""East""],\r\n""points"":[11,8,10,6,6,5],\r\n""rebounds"":[7,7,6,9,12,8]\r\n})\r\n\r\ndef custom_func(x):\r\nreturn x.select(pl.col(""points"").mean())\r\n\r\ndef pl_groupby_progress_apply(data,group_by,func):\r\ngroups=data.group_by(group_by).groups()\r\nresults=[]\r\n\r\nfor _,idx in tqdm(groups.iter_rows(),desc=""Processing groups""):\r\ngroup=data[idx,:]\r\nresults.append(func(group))\r\n\r\nreturn pl.concat(results)\r\n\r\nresult=pl_groupby_progress_apply(df,""team"",custom_func)\r\nprint(result)""]",0

