import hashlib
from color import Color

def get_hash(algorithm):
    hash_func = None
    if algorithm == "sha256":
        hash_func = hashlib.sha256()
    elif algorithm == "sha512":
        hash_func = hashlib.sha512()
    else:
        raise ValueError("Unsupported hash algorithm: {}".format(algorithm))

