    public static void main(String[] args) throws Exception {

        try (Context context = Context.newBuilder("js")
                .option("engine.WarnInterpreterOnly", "false")
                .allowAllAccess(true)
                .build()) {

            Value result = context.eval("js", "2 + 2");
