def nrng_gen():
    yield from range(10)

nrng = nrng_gen()

nrng_func = lambda: next(nrng)

for i in range(10):
    print(nrng_func())

class NRNG:
    def __init__(self):
        self.numbers = range(10)
        self.state = -1
    def __call__(self):
        self.state += 1
        return self.numbers[self.state]

nrng = NRNG()


for i in range(10):
    print(nrng()),"[""def nrng_gen():\r\n    yield from range(10)\r\n\r\nnrng = nrng_gen()\r\n\r\nnrng_func = lambda: next(nrng)\r\n\r\nfor i in range(10):\r\n    print(nrng_func())\r\n\r\nclass NRNG:\r\n    def __init__(self):\r\n        self.numbers = range(10)\r\n        self.state = -1\r\n    def __call__(self):\r\n        self.state += 1\r\n        return self.numbers[self.state]\r\n        \r\nnrng = NRNG()\r\n\r\n\r\nfor i in range(10):\r\n    print(nrng())""]",1

